#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: deploy TOLC Tracker to Netlify with a production Neon database (#12).
# Run from the repo root after the Netlify adapter is merged into main:
#   bash scripts/deploy-wizard.sh
# Production values land in .env.production.local (git-ignored via *.local).
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE=".env.production.local"
DEV_ENV_FILE=".env.local"
TOTAL_STAGES=9

# reuse_dev KEY seeds KEY from .env.local into ENV_FILE (if ENV_FILE doesn't
# have it yet), so the next ask offers it as the default.
reuse_dev() {
  local key="$1" line
  [[ -f "$ENV_FILE" ]] && grep -qE "^${key}=" "$ENV_FILE" && return 0
  [[ -f "$DEV_ENV_FILE" ]] || return 0
  line=$(grep -E "^${key}=" "$DEV_ENV_FILE" | tail -n1) || return 0
  [[ -n "${line#*=}" ]] || return 0
  touch "$ENV_FILE"
  printf '%s\n' "$line" >> "$ENV_FILE"
}

banner "Deploy TOLC Tracker to Netlify"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Neon: production database URL"
say "The app needs its own production database, separate from 'development'."
open_url "https://console.neon.tech/app/projects"
step "Open the TOLC Tracker project."
step "Click Connect. Pick the 'production' branch (the project's default branch)."
step "Leave 'Connection pooling' on, then copy the connection string."
ask_secret DATABASE_URL "Paste the production connection string:"
write_env DATABASE_URL "$DATABASE_URL"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Neon: run migrations and seed the catalogs"
say "This creates the tables in production and loads the Skill and Role Catalogs."
note "Both commands are safe to re-run."
if confirm "Run pnpm db:migrate and pnpm db:seed against PRODUCTION now?"; then
  DATABASE_URL="$DATABASE_URL" pnpm db:migrate
  DATABASE_URL="$DATABASE_URL" pnpm db:seed
  printf '  %s✓ production database ready%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Migrate + seed: DATABASE_URL=<prod> pnpm db:migrate && DATABASE_URL=<prod> pnpm db:seed")
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Netlify: create the site"
open_url "https://app.netlify.com/start"
step "Import from Git → GitHub → pick lindseydortch/tolc-tracker."
step "Branch: main. Leave the build settings blank, since netlify.toml supplies them."
step "Click Deploy. The first deploy builds fine, but sign-in fails until stage 8."
step "Optional: Site configuration → Change site name, to get a nicer URL."
say  "Copy the site's URL (e.g. https://tolc-tracker.netlify.app)."
ask BETTER_AUTH_URL "Paste the site URL:"
BETTER_AUTH_URL="${BETTER_AUTH_URL%/}"
write_env BETTER_AUTH_URL "$BETTER_AUTH_URL"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Better Auth: production secret"
if [[ -n "$(_existing BETTER_AUTH_SECRET || true)" ]]; then
  BETTER_AUTH_SECRET=$(_existing BETTER_AUTH_SECRET)
  say "Keeping the secret already in $ENV_FILE."
else
  BETTER_AUTH_SECRET=$(openssl rand -base64 32)
  say "Generated a fresh secret (different from development)."
fi
write_env BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub: production OAuth app"
say "A GitHub OAuth app allows only one callback URL, so production gets its own app."
open_url "https://github.com/settings/applications/new"
step "Application name: TOLC Tracker"
step "Homepage URL:  $BETTER_AUTH_URL"
step "Authorization callback URL:  $BETTER_AUTH_URL/api/auth/callback/github"
step "Register application, then copy the Client ID."
ask GITHUB_CLIENT_ID "Paste the Client ID:"
step "Click 'Generate a new client secret' and copy it."
ask_secret GITHUB_CLIENT_SECRET "Paste the client secret:"
write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
write_env GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Discord: add the production redirect"
say "Discord allows several redirects, so the existing app is reused."
open_url "https://discord.com/developers/applications"
step "Open the TOLC Tracker app → OAuth2 → Redirects → Add Redirect:"
step "  $BETTER_AUTH_URL/api/auth/callback/discord"
step "Click Save Changes."
note "Enter keeps the credentials from $DEV_ENV_FILE (same Discord app)."
reuse_dev DISCORD_CLIENT_ID
reuse_dev DISCORD_CLIENT_SECRET
ask DISCORD_CLIENT_ID "Discord Client ID:"
ask_secret DISCORD_CLIENT_SECRET "Discord Client Secret:"
write_env DISCORD_CLIENT_ID "$DISCORD_CLIENT_ID"
write_env DISCORD_CLIENT_SECRET "$DISCORD_CLIENT_SECRET"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "TOLC server ID and Admin user ID"
say "These match development. Enter keeps the values from $DEV_ENV_FILE."
reuse_dev TOLC_DISCORD_GUILD_ID
reuse_dev ADMIN_DISCORD_USER_ID
ask TOLC_DISCORD_GUILD_ID "TOLC Discord server ID:"
ask ADMIN_DISCORD_USER_ID "Admin Discord user ID:"
write_env TOLC_DISCORD_GUILD_ID "$TOLC_DISCORD_GUILD_ID"
write_env ADMIN_DISCORD_USER_ID "$ADMIN_DISCORD_USER_ID"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Netlify: environment variables and redeploy"
if command -v pbcopy >/dev/null 2>&1; then
  pbcopy < "$ENV_FILE"
  say "Copied all 9 values from $ENV_FILE to your clipboard."
else
  say "Open $ENV_FILE and copy its contents."
fi
open_url "https://app.netlify.com"
step "Open the site → Site configuration → Environment variables."
step "Add a variable → Import from a .env file → paste → Import variables."
step "Deploys → Trigger deploy → Deploy site (env changes need a fresh deploy)."
step "Wait for the deploy to show Published."
pause "Press Enter once it's published"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Verify the live site"
open_url "$BETTER_AUTH_URL"
step "Sign in with GitHub (the production OAuth app asks to authorize)."
step "Connect Discord. As a TOLC Member, you land on the Directory."
step "Membership gate: a Discord account outside TOLC should be turned away."
step "Directory: the badge wall loads, and filters and search work."
if ! confirm "Did sign-in, the membership gate, and the Directory all work?"; then
  SKIPPED+=("Live verification failed: check Netlify → Logs → Functions")
fi
note "$ENV_FILE holds production secrets. It is git-ignored; delete it if you won't migrate again."

finish
